<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++0x code you have to translate:
<original_code>
#include <cstdio>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

long long v;
vector<long long> cand(17);

int recursive(int index, long long value) {
    value = abs(value);
    if (index == 0) {
        return static_cast<int>(value);
    }
    int quotient = static_cast<int>(value / cand[index]);
    int next_quotient = quotient + 1;
    int option1 = quotient * (index + 1) + recursive(index - 1, value - quotient * cand[index]);
    int option2 = next_quotient * (index + 1) + recursive(index - 1, value - next_quotient * cand[index]);
    return min(option1, option2);
}

int main() {
    scanf("%lld", &v);
    cand[0] = 1;
    for (int i = 1; i < 17; ++i) {
        cand[i] = cand[i - 1] * 10 + 1;
    }
    printf("%d\n", recursive(16, v));
    return 0;
}
